  await password.fill('0003123490');

  const loginButton = await visible(page.getByRole('button', { name: /ログイン|login|Log in|Sign in|サインイン/i }))
    || await visible(page.locator('input[type="submit"], button[type="submit"]'));
  if (!loginButton) throw new Error('ログインボタンが見つかりません。');

  await Promise.allSettled([
    page.waitForLoadState('networkidle', { timeout: 15000 }),
    loginButton.click()
  ]);

  await page.waitForTimeout(3000);
  console.log('LOGIN_ATTEMPTED');
  console.log('URL=' + page.url());
  console.log('TITLE=' + await page.title());
  await browser.close();
})();
